const correctiveArticles: DraftArticle[] = [
  {
    slug: 'philippines-deceased-customer-account-intake',
    title: 'Philippines deceased-customer account intake: route a sensitive case without deciding entitlement',
    excerpt: 'A careful intake path for identity, authority claims, documents, access restrictions, recurring services, and specialist decisions.',
    minutes: 10, image,
    citations: ['https://www.identitytheft.gov/', 'https://www.nist.gov/privacy-framework'],
    keyTakeaways: ['Use a restricted case type with a named specialist owner.', 'Record what the requester claims without deciding inheritance or legal authority.', 'Protect the account while preserving necessary service and billing evidence.'],
    sections: [
      { title: 'Treat the first message as a sensitive claim', body: `A relative writes that an account holder has died and asks support to cancel services, release records, and refund recent charges. The agent should respond with care, but sympathy does not establish authority. Open a restricted case under the client’s deceased-customer procedure and record the account reference, requester’s stated relationship, requested actions, contact channel, date received, urgent service concerns, and any documents offered. Do not copy certificates, identity documents, or family details into ordinary ticket notes. Do not reveal whether the person had an account until the approved verification step permits it. A Philippines-based support specialist can acknowledge the request, explain the approved process, collect only listed fields, and route the case. The client’s legal, privacy, estate, billing, and account owners decide what proof is sufficient, who may act, what information can be disclosed, and whether money or property may move. IdentityTheft.gov is an official US resource for identity misuse and recovery concerns; it does not determine estate authority or the company’s obligations in a particular case.` },
      { title: 'Separate the account from the requester', body: `Create two linked identities in the case record: the customer account under protection and the person making the request. Use the client’s approved method to locate the account without offering hints that help an impostor. Record the requester’s contact details, claimed role, preferred accessible channel, and verification state separately. A spouse, child, executor, trustee, joint user, authorized user, caregiver, or attorney may have different rights, and familiar account activity does not settle the question. If several people contact the company, preserve each claim and route the conflict instead of choosing the most persuasive caller. Never ask for credentials, one-time codes, or access to the deceased person’s email. Check whether the account has active sessions, delegated users, shared assets, recurring orders, stored value, scheduled appointments, or safety-sensitive services. The client owner may authorize protective restrictions while authority is reviewed. Those restrictions should prevent new harm without erasing records or locking out a verified co-owner beyond policy.` },
      { title: 'Build a request map before collecting documents', body: `Different requested actions need different proof and owners. Stopping marketing messages is not the same as closing an account. Cancelling a future shipment differs from refunding a settled payment. Releasing data, transferring a domain, exporting photographs, changing a beneficiary, or paying a balance can require specialized review. For each action, record the governing internal procedure, required evidence list, decision owner, expected review window, and safe interim state. Ask only for documents on that approved list and provide a secure submission route. If a document arrives by an unsafe channel, do not forward it through broad email groups. Move it according to the client’s handling rule or ask the owner for direction. The NIST Privacy Framework offers a way to organize privacy risk and data processing responsibilities, but the client must determine applicable legal requirements. The intake role identifies gaps and keeps the case moving. It does not interpret a will, certify a death record, decide family standing, or declare a document authentic.` },
      { title: 'Coordinate services without making hidden promises', body: `While review is pending, list time-sensitive events: automatic renewals, deliveries, appointments, device access, subscription benefits, payment dates, storage deletion schedules, and communications addressed to the customer. Route each event to its operational owner with the case restriction attached. Use approved holding language that explains the next checkpoint without promising closure, a refund, data release, or a decision date outside the specialist’s control. If a service creates immediate safety or property risk, use the client’s urgent path. Do not cancel first and seek authority later merely to clear the queue. Conversely, do not keep billing indefinitely because the legal review is slow. Escalate the precise conflict with amounts, dates, and reversible options. Keep customer-facing messages consistent across support, billing, fulfilment, and specialist teams. A requester should not receive one answer from chat and a contradictory renewal notice the next day because the case never reached the subscription system.` },
      { title: 'Close only after the authorized outcome is implemented', body: `The final record should show the decision owner, authority basis retained in the restricted repository, approved actions, systems affected, execution references, communications sent, unresolved property or balance, and retention treatment. Verify the actual state: sessions restricted as authorized, recurring services handled, refunds or balances processed only with approval, data access changed, and future notices routed correctly. If the company denies an action or needs more evidence, record the approved explanation and appeal or escalation path. Sample completed cases for excessive data collection, unauthorized disclosure, missed renewals, conflicting claimants, and actions marked done in the ticket but not in the source system. Remove temporary document copies according to policy and preserve the audit record the client requires. This workflow gives a Philippines-based support team a humane, bounded role in a difficult moment while legal authority, disclosure, financial disposition, and account ownership remain with qualified client decision makers.` },
    ],
    internalLinks: [{ label: 'Explore customer experience support', href: '/services/customer-experience-support', note: 'Define sensitive-case intake, access, and escalation.' }, { label: 'Review identity verification controls', href: '/blog/philippines-customer-support-identity-verification-checklist', note: 'Keep verification proportional to the requested action.' }],
    banners: [{ label: 'Sensitive support', title: 'Design the route before the first difficult case', body: 'Map request types, secure evidence intake, specialist ownership, and safe interim states.', href: '/contact-us', linkText: 'Plan the support role' }],
    sources: [{ name: 'IdentityTheft.gov', url: 'https://www.identitytheft.gov/', note: 'Official US recovery resource relevant when identity misuse is suspected.' }, { name: 'NIST Privacy Framework', url: 'https://www.nist.gov/privacy-framework', note: 'Privacy risk-management framework for data processing and governance.' }],
  },
  {
    slug: 'offshore-preorder-deposit-release-reconciliation',
    title: 'Offshore preorder deposit release reconciliation: connect the reservation, balance, shipment, and ledger',
    excerpt: 'A back-office control for preorder deposits when products become ready, customers change plans, or fulfilment splits.',
    minutes: 10, image,
    citations: ['https://www.ftc.gov/legal-library/browse/rules/mail-internet-or-telephone-order-merchandise-rule', 'https://www.consumerfinance.gov/rules-policy/regulations/1026/13/'],
    keyTakeaways: ['Keep the deposit and final charge tied to one reservation record.', 'Release funds or inventory only from an approved readiness event.', 'Reconcile cancellations, expiry, split fulfilment, and failed balance collections separately.'],
    sections: [
      { title: 'Define the preorder states before money moves', body: `A preorder can combine a reservation, a deposit, a promised or estimated availability window, a later balance charge, and fulfilment that starts weeks or months after the first payment. Build a state map for the client’s actual offer: announced, reserved, deposit authorized, deposit settled, production confirmed, allocation assigned, balance notice sent, balance authorized, ready to release, shipped, cancelled, expired, refunded, disputed, or unresolved. Record which event moves an order between states and which owner may approve an exception. A Philippines-based back-office specialist can reconcile these events and prepare customer or finance cases. The client retains pricing, availability promises, cancellation policy, accounting treatment, credit decisions, and release authority. The FTC’s Mail, Internet, or Telephone Order Merchandise Rule is an official US reference for shipment representations and delay options, but counsel determines coverage. Do not call an internal forecast a confirmed ship date or treat a deposit as final revenue merely because the order platform labels the reservation paid.` },
      { title: 'Build a reservation-to-money bridge', body: `For each preorder, link the stable reservation ID, product and variant, quantity, customer record, offer version, deposit amount and currency, processor transaction, remaining balance, tax treatment, discounts, promised or estimated window, allocation event, and fulfilment location. Preserve changes rather than overwriting the original offer. A product configuration may change, a discount can expire, or tax can differ when the balance is collected. Show the approved rule that resolves each difference. Reconcile processor events to the order record: authorization, capture, settlement, reversal, refund, failure, dispute, and retry. A retry must not create two deposits or two final charges. If the company uses separate legal entities or currencies, keep their funds and orders distinct. The specialist flags unmatched deposits, reservations without money, money without a reservation, and balance charges without a readiness event. Accounting and payment owners decide postings, write-offs, credits, and customer remedies.` },
      { title: 'Test readiness before collecting the balance', body: `A warehouse receipt alone may not mean the preorder can ship. Confirm the client’s readiness evidence: accepted inventory, quality release, regulatory or safety clearance where applicable, correct market and variant, packaging, address validation, shipping restriction, and allocation to the specific reservation. Record the evidence version and time. If only part of an order is ready, calculate the permitted balance and shipping treatment under the approved offer. Do not assume the customer wants a split delivery or that the deposit can be applied to any item. Send the approved balance notice through the authorized channel with amount, currency, due event, cancellation options, and truthful availability wording. Payment failure goes to a defined retry or customer-contact path. The specialist should not change the price, substitute a product, extend financing, or release inventory because a customer is urgent. Those are explicit client decisions attached to the reservation.` },
      { title: 'Handle cancellation and expiry as separate outcomes', body: `A customer may cancel before allocation, after allocation but before balance collection, after a failed balance attempt, or after some items ship. A reservation may also expire under the offer’s stated rule. For each event, show deposit disposition, inventory release, final-charge state, refund approval, processor result, customer communication, and ledger effect. Do not mark a deposit refunded when a refund was only requested. Do not return inventory to sale while a client-approved hold remains. Where the customer disputes a charge, link the dispute without issuing an automatic duplicate remedy. The Consumer Financial Protection Bureau’s billing-error regulation is relevant to covered US open-end credit transactions; it does not determine every preorder case. Preserve the offer version and customer messages so the authorized owner can decide a contested promise. One case can contain several line outcomes, but each line should reconcile to one financial and fulfilment state.` },
      { title: 'Close the preorder cohort with control totals', body: `At each release wave, freeze the eligible reservation cohort and total deposits, balances due, balance collections, cancellations, expiries, refunds, disputes, allocated units, shipped units, and unresolved exceptions. Explain the bridge between opening deposits and each closing state. Sample ordinary orders and awkward cases: a variant change, partial allocation, expired card, duplicate retry, address restriction, cancelled line, and delayed shipment after balance collection. Compare order, processor, inventory, customer-support, and ledger records. Carry unresolved cases with stable IDs and named owners rather than recreating them in the next wave. Review whether availability notices matched actual readiness and whether customers received the options promised. A controlled offshore role can do the detailed matching and exception preparation. Product commitment, financial treatment, customer remedy, and inventory-release authority stay with the client.` },
    ],
    internalLinks: [{ label: 'Explore finance operations support', href: '/services/finance-operations-support', note: 'Scope payment reconciliation and exception preparation.' }, { label: 'Review returns and refund reconciliation', href: '/blog/philippines-returns-refund-reconciliation', note: 'Connect later remedies to the original tender.' }],
    banners: [{ label: 'Preorder control', title: 'Reconcile deposits before the release wave', body: 'Map reservation states, payment events, allocation evidence, and approval rights.', href: '/contact-us', linkText: 'Scope the workflow' }],
    sources: [{ name: 'FTC Mail, Internet, or Telephone Order Merchandise Rule', url: 'https://www.ftc.gov/legal-library/browse/rules/mail-internet-or-telephone-order-merchandise-rule', note: 'Official US rule resource on shipment representations and delays.' }, { name: 'CFPB Regulation Z §1026.13', url: 'https://www.consumerfinance.gov/rules-policy/regulations/1026/13/', note: 'Official billing-error rule for covered open-end credit.' }],
  },
  {
    slug: 'philippines-supplier-sanctions-screening-handoff',
    title: 'Philippines supplier sanctions-screening handoff: preserve the match evidence for qualified review',
    excerpt: 'An administrative workflow for supplier identity, screening inputs, possible matches, false-positive evidence, and decision ownership.',
    minutes: 10, image,
    citations: ['https://sanctionssearch.ofac.treas.gov/', 'https://ofac.treasury.gov/faqs/topic/1631'],
    keyTakeaways: ['Screen the approved supplier identity and ownership inputs, not an informal display name.', 'Treat a possible match as a review state, not a violation finding.', 'Keep release, rejection, blocking, and reporting decisions with qualified owners.'],
    sections: [
      { title: 'Prepare an identity record before screening', body: `A supplier named “North Star Trading” appears in a screening result, but the name alone cannot show whether it is the listed party. Start with the approved onboarding sources: legal name, aliases, entity type, registration number, jurisdiction, addresses, ownership information available under the client’s procedure, bank beneficiary where permitted, and service scope. Record the source and retrieval date for each field. Do not collect nationality, personal identifiers, or ownership data beyond the client’s lawful and approved need. A Philippines-based procurement administrator may normalize the record, run an authorized tool, preserve results, and assemble a review packet. They may not decide that a supplier is sanctioned, clear a possible match, interpret sanctions law, block property, reject the supplier, or notify authorities. Those actions stay with the client’s compliance and legal owners. The US Treasury’s Office of Foreign Assets Control provides official list-search tools and guidance, but an automated result is not a legal conclusion and screening requirements depend on the organization and transaction.` },
      { title: 'Record the search so another reviewer can reproduce it', body: `The screening record should include tool and dataset, search time and timezone, list version or update time where available, fields submitted, matching threshold, transliteration settings, filters, result identifiers, and unaltered result output. Preserve a protected copy or durable reference according to policy. If the tool searches only a name while the client expects address or identifier comparison, flag the limitation. Do not manipulate spelling until a result disappears. Run approved aliases and transliterations as separate attributable searches. A “no match” result means the configured search returned none at that time; it does not prove the supplier or every owner is clear. Likewise, a high score does not prove identity. Screening vendors can rank similarities differently. The handoff should let the qualified reviewer see which facts agree, which conflict, which are missing, and what source supports each comparison without repeating the search from memory.` },
      { title: 'Build a possible-match comparison without making the decision', body: `Use a side-by-side table for name and aliases, entity or person type, jurisdiction, address, date or registration identifiers, ownership connections, list program, and source confidence. Mark exact agreement, material conflict, partial information, and unavailable evidence. Do not use a single mismatch as automatic clearance unless the client’s qualified procedure says it is dispositive. A supplier can share a common name with a listed party, while an alias can differ substantially. Separate factual comparison from inference. “Addresses differ” is a fact when both sources are current; “therefore false positive” is a decision. Record commercial urgency and pending transactions, but never let a payment deadline lower the evidentiary standard. Place affected onboarding, purchase, access, or payment activity in the client’s prescribed hold state. The administrator communicates only approved status language and does not accuse the supplier or disclose sensitive screening logic.` },
      { title: 'Route the result through named decision states', body: `Define states such as prepared, screened, no result under stated configuration, possible match, awaiting evidence, under qualified review, cleared by owner, rejected by owner, blocked or restricted under owner instruction, and rescreen required. Every transition names the actor, time, evidence, and permitted next action. An email saying “looks fine” is not enough if the procedure requires a case decision. The compliance owner may request a registration extract, ownership confirmation, or another source through an approved channel. The administrator tracks that request without deciding what evidence is legally sufficient. OFAC’s Sanctions List Search and its guidance on search results explain that users must assess potential matches; the client’s advisers determine the correct response. If instructions conflict, keep the supplier and affected transaction on hold and escalate. Do not delete the first result after later clearance because the history explains why work paused and what the reviewer considered.` },
      { title: 'Rescreen when relevant facts change', body: `Approval is time-bound to the identity, ownership, lists, and transaction context reviewed. Define rescreen triggers: list updates under client policy, legal-name or ownership change, new jurisdiction, bank-beneficiary change, long inactivity, contract renewal, unusual transaction, or scheduled periodic review. Reconcile active suppliers to the screening register and investigate missing or stale records. Sample cleared possible matches to confirm the comparison and decision evidence remain linked. Test the process with a common name, transliterated alias, changed address, incomplete registration, corporate parent, and supplier whose bank beneficiary differs. Measure preparation completeness, review aging, unsupported releases, stale screening, and downstream holds left active after a decision. Do not rank administrators by quick clearances. The useful outcome is a reproducible packet that allows qualified owners to decide while the offshore role manages evidence, follow-up, and system state without taking compliance authority.` },
    ],
    internalLinks: [{ label: 'Explore procurement administration', href: '/services/procurement-administration', note: 'Define supplier evidence and qualified review handoffs.' }, { label: 'Browse the blog library', href: '/blog', note: 'Connect screening state to the wider onboarding gate.' }],
    banners: [{ label: 'Supplier review', title: 'Keep possible-match evidence reproducible', body: 'Map approved identity sources, screening configuration, holds, and decision owners.', href: '/contact-us', linkText: 'Plan the workflow' }],
    sources: [{ name: 'OFAC Sanctions List Search', url: 'https://sanctionssearch.ofac.treas.gov/', note: 'Official US Treasury list-search resource.' }, { name: 'OFAC Sanctions List Search FAQs', url: 'https://ofac.treasury.gov/faqs/topic/1631', note: 'Official guidance about use and interpretation of search results.' }],
  },
  {
    slug: 'offshore-corporate-annual-filing-evidence-calendar',
    title: 'Offshore corporate annual-filing evidence calendar: coordinate the record without giving legal advice',
    excerpt: 'A jurisdiction-specific register for entity identity, source notices, preparation dependencies, approval, filing proof, and status reconciliation.',
    minutes: 10, image,
    citations: ['https://www.sba.gov/business-guide/launch-your-business/register-your-business', 'https://www.irs.gov/businesses/small-businesses-self-employed/recordkeeping'],
    keyTakeaways: ['Use the official entity record and qualified owner’s deadline rule.', 'Separate document preparation from legal certification and submission authority.', 'Close only after filing evidence and official status reconcile.'],
    sections: [
      { title: 'Build the entity population before the calendar', body: `A group may have corporations, limited liability companies, foreign registrations, dormant entities, trade names, and entities in dissolution. Start with the client’s approved legal-entity register and reconcile it to official records or notices selected by the legal or corporate-secretary owner. Record legal name, registration number, jurisdiction, entity type, status, registered agent or official contact, fiscal information needed by the procedure, and accountable owner. Do not infer that a similar name is the same entity or remove a dormant company because it had no recent transactions. A Philippines-based administrator can maintain the register, collect source notices, prepare standard data, request dependencies, and preserve filing evidence. The client’s legal, tax, finance, and corporate owners decide what must be filed, the deadline, certifications, elections, fees, signatures, and consequences. The US Small Business Administration explains that registration and ongoing requirements vary by location and structure. It is a starting reference, not a deadline calculator for a particular entity.` },
      { title: 'Store the deadline rule with the date', body: `Every calendar item needs the filing name, governing jurisdiction, entity, period, trigger, calculation rule approved by the owner, official source, due date and timezone, early preparation date, fee information, delivery channel, signer, approver, and evidence required for closure. Distinguish annual reports, franchise or information filings, registered-agent renewals, business licenses, beneficial-ownership processes, tax returns, and internal board actions. Similar names do not mean the same authority or date. If the rule changes or a notice conflicts with the calendar, place the item under review and preserve both sources. Do not move the date to make a dashboard green. Calendar reminders should begin early enough for ownership, address, officer, financial, or signature changes to be approved. A date copied from last year is provisional until the responsible owner confirms it still applies to the current entity and period.` },
      { title: 'Prepare a filing pack with explicit certification boundaries', body: `The preparation pack contains the approved source form or portal reference, prior filing, current entity details from governed systems, changes since the prior period, supporting approvals, fee route, signer requirement, unresolved questions, and a field-level comparison. The administrator may populate routine fields under written instruction and flag differences. They should not choose an entity classification, interpret a question, certify accuracy, select a tax or legal position, appoint an officer, or sign for the company without specific authority. Protect personal addresses and identifiers. Use the official portal or client-approved system, not a link from an unsolicited renewal notice. If a third-party solicitation resembles a government form, route it to the owner before payment. The IRS recordkeeping page provides general US business-record guidance, while the client sets applicable retention and filing evidence. Each pack should make unanswered questions visible rather than filling them with last year’s value.` },
      { title: 'Control submission and payment', body: `Approval attaches to the exact form values, entity, period, signer, and fee. A later edit reopens the affected review. The authorized submitter verifies the destination, account, entity identifier, reporting period, attachments, signature, payment amount, and return contact. Record the portal receipt, confirmation number, submitted copy, timestamp, and payment reference. A browser message saying “submitted” is not final evidence if the jurisdiction later rejects the filing. Track accepted, pending, returned, rejected, corrected, withdrawn, and unresolved states. If the portal is unavailable near the deadline, use the client’s escalation and contingency procedure; the administrator must not choose an unofficial filing service. Avoid duplicate payment by checking the case before retrying. When rejection arrives, preserve the first submission and route the exact reason, required correction, and deadline to the owner.` },
      { title: 'Reconcile official status after filing', body: `After the expected processing window, compare the official entity status or acknowledgment with the submitted record. Confirm that the filing attached to the correct entity and period, approved changes appear, payment settled, and any follow-up has an owner. A receipt without accepted status can leave the entity unresolved. Sample the annual register against official sources and accounting records for fees. Review missed dependencies, late approvals, returned filings, duplicate charges, stale entity ownership, and reminders sent to departed people. Preserve previous years and amendments rather than overwriting them. Test absence coverage and a legal-name change before the next cycle. The offshore role improves control through careful population management, preparation, and follow-up. It never converts a calendar into legal advice or a filing receipt into a conclusion about good standing beyond the official evidence and qualified owner’s interpretation.` },
    ],
    internalLinks: [{ label: 'Explore shared services administration', href: '/services/shared-services-administration', note: 'Scope entity-record preparation and follow-up.' }, { label: 'Browse the blog library', href: '/blog', note: 'Keep filing evidence in its governed repository.' }],
    banners: [{ label: 'Corporate administration', title: 'Build the entity register before reminders fire', body: 'Define official sources, qualified owners, filing packs, submission rights, and acceptance evidence.', href: '/contact-us', linkText: 'Scope the role' }],
    sources: [{ name: 'US SBA: Register your business', url: 'https://www.sba.gov/business-guide/launch-your-business/register-your-business', note: 'Official overview of registration and location-specific requirements.' }, { name: 'IRS Recordkeeping', url: 'https://www.irs.gov/businesses/small-businesses-self-employed/recordkeeping', note: 'Official general guidance on business records.' }],
  },
  {
    slug: 'philippines-merchant-processor-reserve-reconciliation',
    title: 'Philippines merchant processor reserve reconciliation: explain held funds without guessing release',
    excerpt: 'A finance-support bridge from processor activity and reserve rules to cash, ledger, release events, and owned exceptions.',
    minutes: 10, image,
    citations: ['https://www.consumerfinance.gov/rules-policy/regulations/1026/13/', 'https://www.federalreserve.gov/paymentsystems.htm'],
    keyTakeaways: ['Separate sales settlement, fees, refunds, disputes, and reserve movements.', 'Tie every reserve hold or release to processor evidence and the approved agreement interpretation.', 'Do not present an estimated release as available cash.'],
    sections: [
      { title: 'Name the balances before reconciling them', body: `A processor dashboard shows gross sales, net payout, rolling reserve, dispute hold, negative balance, and “available soon.” Those labels can mean different things across providers. The client’s finance and contract owners should define each balance using the processor agreement and approved accounting policy. A Philippines-based finance specialist can capture statements, map transaction classes, calculate the bridge, and investigate discrepancies. They cannot interpret the contract, recognize revenue, choose accounting treatment, promise a release date, or move money. Start with processor account, legal entity, merchant ID, currency, settlement account, statement period, payout schedule, reserve type, and source timestamp. Keep multiple merchant accounts separate. The Federal Reserve’s payment-systems resources give general official context for US payment infrastructure, but they do not explain a specific processor reserve. The control begins with the processor’s governed records and the client’s approved interpretation, not a generic assumption about when held cash becomes available.` },
      { title: 'Create a daily funds bridge', body: `Begin with opening processor receivable and reserve balances. Add captured transactions that belong to the period. Subtract refunds, disputes, processor fees, network or service charges, taxes withheld under the client’s setup, reserve additions, and payouts. Add reserve releases and dispute reversals as distinct classes. End at closing receivable, reserve, and other held balances. Reconcile each class to transaction-level reports and the bank statement. Preserve timezone, settlement cutoff, currency conversion, and late-arriving activity. A payout spanning midnight can belong to a different operational day from the sales report. Do not plug the difference into fees or reserve merely to balance the sheet. Put unexplained values in a named exception with amount, source, and next owner. Where the processor nets several currencies or entities, use the approved allocation evidence and expose what cannot be separated.` },
      { title: 'Track reserve lots and release conditions', body: `A rolling reserve may hold a percentage of each eligible transaction for a stated period, while a fixed reserve or risk hold may follow another rule. Create reserve lots only if the processor data and approved method support them. Each lot records originating cohort, amount, currency, hold date, stated basis, expected review or release event, actual release, adjustment, and source. Label estimated release dates as estimates. A release can be offset by new disputes or a negative balance, so gross release and net cash should remain distinct. If the processor changes the percentage or extends a hold, preserve the notice and effective date and route the contractual question. The specialist can compare observed calculations with the approved rule, but the processor relationship owner decides whether to challenge an amount. Never tell management that restricted funds are available merely because a schedule predicts release.` },
      { title: 'Connect exceptions to customer and dispute systems', body: `Reserve differences often originate outside treasury. Link large or unusual movements to refund batches, chargebacks, fraud holds, fulfilment events, or account-level adjustments without copying unnecessary customer data into the reconciliation. Use stable transaction and case identifiers. The Consumer Financial Protection Bureau’s billing-error regulation applies to covered US open-end credit disputes and helps explain why dispute events can have their own timelines; it does not determine processor reserve treatment. Separate a customer remedy from the processor’s decision to hold funds. A refund can be valid while its reserve effect remains unexplained. Route missing dispute documents to the operations owner and contract questions to the merchant-acquiring owner. If source reports change after close, append a versioned adjustment rather than replacing the frozen evidence. One reviewer should reproduce a sample across processor, bank, customer case, and ledger.` },
      { title: 'Report liquidity without overstating certainty', body: `The close package shows opening and closing reserve, additions, releases, adjustments, aging by stated release event, expected versus actual releases, unexplained differences, and the bridge to cash and ledger. Identify processor-reported available balance separately from company-controlled bank cash. Include known data latency and contractual uncertainty. Review old reserve lots, repeated schedule misses, unexplained fee reclassification, duplicate payouts, negative balances, and differences that recur at timezone cutoff. Test one month with a large refund batch, a dispute reversal, currency conversion, and a delayed payout. The finance owner approves accounting and liquidity presentation. The offshore specialist maintains the evidence and exception trail. This produces a useful cash-control role without asking an administrator to forecast processor behavior or make contractual and accounting judgments they do not own.` },
    ],
    internalLinks: [{ label: 'Explore finance operations support', href: '/services/finance-operations-support', note: 'Scope processor reconciliation and exception preparation.' }, { label: 'Browse the blog library', href: '/blog', note: 'Connect control totals to source evidence.' }],
    banners: [{ label: 'Payments operations', title: 'Explain reserve movement before forecasting cash', body: 'Map processor balances, transaction classes, release evidence, and finance decisions.', href: '/contact-us', linkText: 'Plan the workflow' }],
    sources: [{ name: 'Federal Reserve payment systems', url: 'https://www.federalreserve.gov/paymentsystems.htm', note: 'Official general information on US payment systems.' }, { name: 'CFPB Regulation Z §1026.13', url: 'https://www.consumerfinance.gov/rules-policy/regulations/1026/13/', note: 'Official billing-error rule for covered open-end credit disputes.' }],
  },
  {
    slug: 'offshore-field-service-appointment-readiness-handoff',
    title: 'Offshore field-service appointment readiness handoff: confirm the visit can succeed before dispatch',
    excerpt: 'A pre-dispatch review for customer access, technician skills, parts, permits, safety notes, travel, and fallback communication.',
    minutes: 10, image,
    citations: ['https://www.osha.gov/safety-management', 'https://www.nist.gov/privacy-framework'],
    keyTakeaways: ['Define readiness separately from a booked calendar slot.', 'Confirm customer, technician, parts, access, and safety dependencies through their owners.', 'Use a controlled fallback when a dependency fails before dispatch.'],
    sections: [
      { title: 'A booking is not a ready appointment', body: `A calendar may show a technician due tomorrow even though the required part is still in transit, the building needs a permit, and nobody confirmed access after hours. Define appointment readiness as a set of accepted conditions, not a green calendar cell. The conditions vary by service, but can include verified customer and site, approved work order, service scope, technician skill or certification, parts and tools, route and travel window, access contact, permit or landlord approval, safety information, equipment shutdown, and customer preparation. A Philippines-based coordinator can collect evidence, chase dependencies, maintain status, and send approved updates. Dispatch, safety, technical diagnosis, scope changes, pricing, and customer remedies remain with client owners. OSHA’s Recommended Practices for Safety and Health Programs provide official general principles for hazard identification, worker participation, and prevention. The client’s qualified safety and technical teams determine what a particular visit requires.` },
      { title: 'Build the readiness card around the actual job', body: `The card identifies work-order ID, site, asset, requested outcome, approved scope, appointment window and timezone, customer contact, access instructions, technician or crew, required competence, parts and tools, safety or privacy flags, upstream approvals, and evidence owner for each condition. Avoid copying door codes, medical details, or security layouts into a broad scheduling board. Link to protected systems and reveal only what the assigned role needs. Mark each dependency confirmed, missing, conflicting, expired, or not applicable with a reason. A customer’s verbal description may differ from the work order; preserve both and route the scope question. Do not tell the technician to “figure it out onsite” when the mismatch affects safety, cost, or first-time completion. The coordinator’s job is to make the gap visible early enough for an authorized decision.` },
      { title: 'Verify parts without reserving the wrong stock', body: `Match part number, revision, compatible asset, quantity, warehouse or vehicle location, reservation status, expected arrival, and inspection state. A tracking number does not prove the correct part is available for this visit. If another work order competes for the item, the inventory or dispatch owner decides allocation. Record consumables and specialist tools separately because a stocked replacement can still be unusable without them. Where the technician will diagnose before choosing a part, label the visit diagnostic and set the customer expectation accordingly. Do not convert an uncertain repair into a guaranteed completion. For customer-supplied equipment, follow the client’s acceptance and safety procedure. If the part changes after readiness review, reopen the relevant checks, including skill, time, price authorization, and customer communication. Preserve the prior reservation so missing stock can be traced rather than blamed on the last coordinator.` },
      { title: 'Run a timed go, hold, or reschedule decision', body: `Set checkpoints based on travel and customer consequence. At the final checkpoint, the dispatch owner chooses go, hold for a bounded dependency, change technician, convert scope, or reschedule under policy. The packet shows what is ready, what is not, customer effect, safe alternatives, and latest decision time. A coordinator may send an approved reschedule or arrival message only after the decision. They should not pressure a technician to accept unsafe work, ask a customer to waive a requirement casually, or promise compensation. If a technician is already travelling when new information arrives, use the client’s urgent route. Record acknowledgments from dispatch, technician, and customer where required. Silence does not prove the building will open or the customer accepted a new window. The NIST Privacy Framework is relevant when site and customer data is processed; collect and expose only what the visit needs.` },
      { title: 'Learn from avoidable failed visits', body: `After service, reconcile arrival, access, work performed, parts used, scope changes, completion evidence, follow-up, and customer communication. Classify a failed or partial visit by the dependency that actually failed: customer access, incorrect scope, technician skill, part, tool, travel, permit, safety condition, system outage, or new diagnosis. Do not assign every failure to scheduling. Sample successful visits because they show whether the checklist adds value or merely accumulates confirmations. Track readiness at checkpoint, late changes, preventable dispatches, customer recontacts, parts returned, and follow-up aging. Update the card when service design changes, then test a night visit, multi-tenant building, wrong asset serial, delayed part, and absent site contact. The result is a field-service coordination role that improves first-visit conditions while technical, safety, commercial, and dispatch authority remain with the client.` },
    ],
    internalLinks: [{ label: 'Explore project coordination support', href: '/services/project-coordination-support', note: 'Scope dependency follow-up and appointment handoffs.' }, { label: 'Browse the blog library', href: '/blog', note: 'Use evidence-based go and hold decisions.' }],
    banners: [{ label: 'Field coordination', title: 'Check readiness before the vehicle moves', body: 'Define dependencies, evidence owners, decision checkpoints, and customer updates.', href: '/contact-us', linkText: 'Scope the role' }],
    sources: [{ name: 'OSHA Recommended Practices for Safety and Health Programs', url: 'https://www.osha.gov/safety-management', note: 'Official general safety-program principles.' }, { name: 'NIST Privacy Framework', url: 'https://www.nist.gov/privacy-framework', note: 'Privacy risk-management framework for customer and site information.' }],
  },
  {
    slug: 'philippines-board-conflict-disclosure-routing',
    title: 'Philippines board conflict-disclosure routing: protect the record before materials and votes move',
    excerpt: 'An executive-support workflow for declarations, agenda links, restricted access, recusals, minutes inputs, and qualified decisions.',
    minutes: 10, image,
    citations: ['https://www.sec.gov/corpfin', 'https://www.archives.gov/records-mgmt/policy'],
    keyTakeaways: ['Route a declaration without deciding whether a conflict exists.', 'Connect the approved handling instruction to agenda access, attendance, voting, and minutes preparation.', 'Keep restricted facts and legal advice out of the general board pack.'],
    sections: [
      { title: 'Open a restricted declaration record', body: `A director tells the chair’s assistant that a family member has joined a bidder shortly before procurement appears on the agenda. The coordinator should not decide whether this is a legal conflict or harmless background. Open a restricted record with declarant, meeting or matter, date received, exact facts volunteered, source, urgency, and designated governance or legal owner. Acknowledge receipt using approved language and explain the next procedural checkpoint without promising an outcome. Do not ask for broad family, financial, or employment information beyond the approved form. Keep the declaration outside ordinary agenda notes and chat. A Philippines-based executive-support specialist can route the record, track owner instructions, manage permitted access, and prepare administrative evidence. The chair, company secretary, board, legal counsel, ethics owner, or other client authority decides materiality, disclosure, recusal, attendance, voting, and minutes treatment. SEC Corporation Finance resources concern US federal securities disclosure and filing matters; they do not determine a private board’s conflict procedure.` },
      { title: 'Link the declaration to the correct matter', body: `Use a stable matter or agenda identifier rather than copying the sensitive narrative into every calendar item. Record related entity, transaction, paper, committee, meeting date, and decision stage only to the extent approved. A declaration can affect one agenda item without restricting unrelated board work. Conversely, a broad relationship may touch several linked decisions. The qualified owner defines scope. The coordinator checks the board portal, distribution groups, calendar, attendee list, and paper workflow for the impacted matter. If papers have already been distributed, preserve that fact and seek an instruction; do not delete access logs or quietly replace the pack. If identity or relationship is unclear, route the precise question. Avoid labeling a person “conflicted” before the owner decides. Status should distinguish declared, under review, instruction issued, implemented, superseded, closed, and unresolved.` },
      { title: 'Turn the owner instruction into operational controls', body: `The instruction may require no change, a disclosure to named participants, limited paper access, absence during discussion, abstention from a vote, alternate approval, or another action under the client’s governance rules. Record the exact scope, effective meeting or period, approving owner, people permitted to know, implementation tasks, and evidence. Update portal permissions, distribution lists, meeting run sheet, voting process, and minutes brief only as instructed. Test access with a non-sensitive indicator where possible; do not expose the paper while checking removal. The meeting chair and company secretary need an actionable cue without receiving unnecessary personal details. A substitute attendee or decision owner must have actual authority, not merely calendar availability. If the instruction changes minutes wording or disclosure, preserve versions and approval. The administrator cannot expand a recusal because it seems prudent or narrow it because the meeting is urgent.` },
      { title: 'Handle late and in-meeting disclosures', body: `A participant may raise a relationship during discussion after papers are open. The meeting runbook should name who pauses the item, who receives the declaration, where the participant waits if asked to leave, how quorum or voting questions reach the qualified owner, and how the record is preserved. The offshore coordinator can timestamp the event and support the chair’s authorized instruction. They should not advise the meeting on legal effect. If no authorized owner is reachable, use the predefined safe state rather than continuing by assumption. Capture the decision that actually occurred, including deferred consideration, and reconcile portal access afterward. Do not rewrite the original agenda or recording metadata to make the disclosure appear earlier. The minutes preparer receives only the approved facts and wording. Restricted supporting detail stays in its designated record with access logs and retention treatment.` },
      { title: 'Reconcile the board record after the meeting', body: `Compare the instruction with attendance, paper access, discussion timing, voting or written-consent evidence, minutes draft, action assignments, and any required disclosure workflow. A portal permission change alone does not prove a person left the discussion, and an abstention note does not prove the correct matter was isolated. Route discrepancies to the company secretary or governance owner. Review declarations that recur across committees or connected transactions without merging them beyond authority. Remove temporary access changes when instructed and preserve the audit trail. The US National Archives records-management policy resources provide useful questions about official records and lifecycle control, but the client determines what board records must be kept. Test the process with a late disclosure, remote attendee, paper downloaded before restriction, changed agenda, and written consent outside a meeting. The role succeeds when qualified decisions become accurate operational steps without spreading sensitive facts or turning administrative coordination into legal judgment.` },
    ],
    internalLinks: [{ label: 'Explore shared services administration', href: '/services/shared-services-administration', note: 'Scope restricted governance coordination and evidence.' }, { label: 'Browse the blog library', href: '/blog', note: 'Keep approved context and uncertainty visible.' }],
    banners: [{ label: 'Board support', title: 'Route declarations before access and votes move', body: 'Define restricted intake, qualified decisions, operational controls, and minutes evidence.', href: '/contact-us', linkText: 'Plan the workflow' }],
    sources: [{ name: 'SEC Division of Corporation Finance', url: 'https://www.sec.gov/corpfin', note: 'Official federal securities disclosure and filing resources; applicability requires qualified review.' }, { name: 'US National Archives records management policy', url: 'https://www.archives.gov/records-mgmt/policy', note: 'Official records-management policy resources.' }],
  },
];

const correctiveSupplementalSections: Record<string, { title: string; body: string }> = {
  'philippines-deceased-customer-account-intake': {
    title: 'Practice the cases where ordinary verification breaks down',
    body: `Training should include a joint account where one holder remains active, a subscription paid by a different cardholder, a business account whose sole administrator died, a requester who knows extensive account history but has no approved authority evidence, and two relatives giving conflicting instructions. Add an urgent delivery and a digital asset that could be deleted by an automated retention rule. For each case, ask the specialist to identify what may be acknowledged, which data remains restricted, which reversible protection is available, and which owner must decide. Score the quality of the handoff, not whether the coordinator guessed the eventual outcome. The case should remain understandable after a shift change without exposing sensitive documents. Reviewers should also test language. Avoid asking a grieving person to repeat details already recorded, but do not use empathy as a reason to bypass identity and disclosure rules. Give the requester a clear case reference, secure submission path, next checkpoint, and contact route. If the client cannot name the specialist owner or safe interim state, fix that governance gap before assigning live cases to the offshore queue.`,
  },
  'offshore-preorder-deposit-release-reconciliation': {
    title: 'Test the release wave before sending customer notices',
    body: `Run a dry reconciliation on a frozen sample before the live wave. Include a fully paid reservation, deposit plus balance, failed card, changed address, tax difference, split product bundle, allocation shortage, customer cancellation, prior dispute, and reservation duplicated during a platform migration. Confirm that each record produces one permitted notice and one financial next action. Compare the audience file with consent and contact preferences, and suppress accounts already resolved through support. Use synthetic recipients for rendering and link tests. The operations owner reviews inventory allocation, finance reviews charge and refund states, and customer support reviews wording and reply capacity. A specialist should be able to explain why every record entered or left the cohort. After the real wave, reconcile intended, attempted, successful, failed, and suppressed notices with balance attempts and inventory release. A clean email campaign does not prove the money or stock moved correctly. Keep exceptions open until processor, order, warehouse, customer message, and ledger show an explainable state. This rehearsal catches configuration errors before they affect an entire preorder population. Record the approved cohort and test evidence so the live release can be compared with the exact rehearsal rather than a later export.`,
  },
  'philippines-supplier-sanctions-screening-handoff': {
    title: 'Control screening-tool and list changes',
    body: `Screening results can change when a vendor updates its matching algorithm, a list source changes format, thresholds move, or the client enables another dataset. Record configuration ownership and require a change notice that identifies effective time, affected populations, test cases, and rollback. Before release, compare known clear, known possible-match, alias, common-name, and incomplete-record examples under old and new settings. Do not use real restricted cases in a broad test environment. If a configuration change creates a large new queue, preserve prior results and prioritize through the qualified owner’s rule rather than lowering the threshold to reduce volume. Reconcile users and permissions after the change. The administrator may execute an approved rescreen and report result movement, but cannot declare the new configuration legally sufficient. Keep list-update time distinct from the time a supplier was rescreened. When a historical result cannot be reproduced because the tool or data changed, document that limitation and retain the original output. This gives reviewers a defensible history instead of a dashboard that silently applies today’s logic to yesterday’s decision. Record the test approver too.`,
  },
  'offshore-corporate-annual-filing-evidence-calendar': {
    title: 'Run a pre-season calendar challenge',
    body: `Before the busiest filing period, select a sample across jurisdictions and entity states. Recalculate each approved deadline from its source, confirm the official portal and account, test signer and backup access, locate the prior accepted filing, and verify the fee route. Include a foreign registration, an entity with a recent officer change, a dormant company, a rejected prior filing, and an entity expected to dissolve. Ask the qualified owner to resolve any unclear requirement before preparation begins. Simulate a portal outage and an absent signer without submitting anything. The exercise should expose whether the calendar depends on one person’s bookmarks or memory. Review notification delivery to role-based backups and remove departed recipients. Confirm that the administrator can distinguish a commercial solicitation from an official notice without making a legal conclusion: uncertain notices go to the owner with source details. Record each test, defect, owner, and correction. A successful rehearsal means the organization can produce the approved entity record, calculate the controlled date, prepare the correct pack, and preserve submission evidence under ordinary and disrupted conditions. Repeat affected checks after an entity conversion, registered-agent change, filing-system migration, or acquisition alters the population.`,
  },
  'philippines-merchant-processor-reserve-reconciliation': {
    title: 'Investigate a reserve difference without plugging it',
    body: `Suppose the closing reserve is $18,420 higher than the lot schedule predicts. Freeze the statement, transaction export, payout report, bank activity, and ledger extract with retrieval times. Recalculate each class and check whether the difference comes from a new reserve rate, shifted settlement cutoff, currency conversion, dispute hold, refund batch, negative-balance offset, late transaction, or report revision. Compare gross and net views because a release may be hidden inside a payout reduced by new holds. Do not post the difference to fees or miscellaneous receivable merely to balance. Prepare a question that identifies merchant account, currency, period, expected amount, observed amount, evidence, and competing explanations. The processor relationship owner decides whether and how to challenge it; finance decides interim accounting. When a response arrives, preserve it as attributed processor information and verify the next statement or payout. Close the exception only when the bridge and approved ledger treatment agree. This worked method gives the offshore specialist a concrete investigation path without turning uncertainty into invented cash. If the next statement revises earlier transactions, retain both versions and show which reserve lots moved. Check that a correction did not create a second ledger adjustment or conceal a separate payout difference. Assign every residual amount, however small, to an owner or approved threshold rule.`,
  },
  'offshore-field-service-appointment-readiness-handoff': {
    title: 'Design the customer confirmation around real constraints',
    body: `The confirmation should state the appointment window and timezone, site address, contact method, approved preparation steps, access needs, expected service scope, items the customer must not operate or move, and the route for changes. Include only instructions approved by technical and safety owners. Do not ask a customer to diagnose equipment, bypass a lockout, handle a hazardous part, or make an unsafe area accessible. Verify accessibility and language needs early enough to arrange support. If arrival depends on traffic, earlier jobs, permits, or a part delivery, use truthful window language and a named update checkpoint. Record delivery and acknowledgment separately. A sent text does not prove the site contact received it. Where several tenants or departments share the location, identify the authorized contact and asset without exposing unrelated customer information. Reconfirm material changes with dispatch and the assigned technician. Good customer communication reduces avoidable failure, but it cannot compensate for missing parts, unsuitable skills, or an unresolved hazard. Those dependencies must remain visible until their owners accept them. Give the customer a case reference that survives a channel change. If they withdraw access or report a new hazard, pause the readiness state and alert dispatch instead of burying the update in free text. After the visit, compare promised arrival communications with actual events and correct stale templates.`,
  },
  'philippines-board-conflict-disclosure-routing': {
    title: 'Audit access without exposing the declaration',
    body: `A periodic control review can use matter IDs and handling states rather than sensitive narratives. Select declared matters and compare owner instruction with portal permissions, distribution events, attendance records, voting evidence where maintained, approved minutes language, and restoration of ordinary access. Limit reviewers to the evidence they are authorized to see. A portal log may show that someone opened a paper before restriction; preserve the event and route it rather than deleting the record. Conversely, lack of an access event does not prove the person left a live discussion. Match each control to the evidence it can actually support. Check role changes, committee membership, guest accounts, downloaded copies under the client’s procedure, and recurring agenda items. Report implementation gaps without restating personal details. The governance owner decides consequence and remediation. Review the register for declarations stuck under review, instructions without implementation proof, temporary restrictions never removed, and meeting records awaiting approved wording. This audit keeps administrative execution faithful to the qualified decision while respecting the confidentiality that made a restricted route necessary. Record when the next review is due and who owns it.`,
  },
};

for (const article of correctiveArticles) article.sections.push(correctiveSupplementalSections[article.slug]);

const correctiveClosers: Record<string, { title: string; body: string }> = {
  'offshore-corporate-annual-filing-evidence-calendar': { title: 'Preserve the rehearsal decision', body: 'Keep a dated owner sign-off for the pre-season test and verify every assigned repair before the first live filing deadline enters its preparation window.' },
  'philippines-merchant-processor-reserve-reconciliation': { title: 'Retest changed exports', body: 'Run the bridge again when the processor changes statement layouts, payout identifiers, reserve labels, currencies, or cutoff behavior, and preserve the comparison.' },
  'offshore-field-service-appointment-readiness-handoff': { title: 'Compare the card with the visit', body: 'Ask dispatch and the technician whether the readiness record matched the site, asset, parts, access, and hazards they encountered, then assign specific corrections.' },
  'philippines-board-conflict-disclosure-routing': { title: 'Dispose of working copies', body: 'After the governed record is complete, confirm that temporary restricted copies are removed under the approved retention instruction without deleting the required audit trail.' },
};
for (const article of correctiveArticles) {
  const closer = correctiveClosers[article.slug];
  if (closer) article.sections.push(closer);
}

